import numpy as np
def pool_out(n, k, s, p=0):
    return (n + 2*p - k)//s + 1
cases = [(28,3,2,0),(28,2,2,0),(32,2,2,0),(224,2,2,0),(13,3,2,0),(13,2,2,0),(224,3,2,1)]
print("输入 核 步长 填充 -> 池化输出尺寸")
for n,k,s,p in cases:
    print(f"  n={n} k={k} s={s} p={p} -> out={pool_out(n,k,s,p)}")
